// Package models is the orm-gen test input.
package models

import (
	"time"

	db "orm"
)

// Audit is embedded by value: its fields are columns of the model.
type Audit struct {
	CreatedBy string `db:"created_by"`
	note      string `db:"note"` // unexported: not a column
}

type Status string

type User struct {
	db.BaseModel
	Name, Nick string     `db:"name"` // two fields, one tag: both scanned, the first one's value
	Email      string     `db:"email"`
	Status     Status     `db:"status"`
	Born       *time.Time `db:"born"`
	Skip       string     `db:"-"`
	Plain      string
	Posts      []Post `rel:"posts"`
	Audit
	db.Timestamps
	db.SoftDeletes
	hidden string `db:"hidden"`
}

func (User) TableName() string { return "users" }

type Post struct {
	ID     int64  `db:"id"`
	UserID int64  `db:"user_id"`
	Title  string `db:"title"`
}

func (Post) TableName() string { return "posts" }

// NoColumns has no db tags and is not generated by default.
type NoColumns struct {
	A string
}

// Box is generic and is skipped by default.
type Box[T any] struct {
	V T `db:"v"`
}
